# 实用例子：计算阶乘，提前返回边界条件
def factorial(n):
    if n < 0:
        return None  # 负数没有阶乘
    if n <= 1:
        return 1
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

print(factorial(5))  # 120

