# 简单装饰器：记录函数调用
def log(func):
    def wrapper(*args, **kwargs):
        print(f'调用函数：{func.__name__}，参数：{args} {kwargs}')
        result = func(*args, **kwargs)
        print(f'函数 {func.__name__} 执行完毕')
        return result
    return wrapper

