# 自定义迭代器：倒数
class Countdown:
    def __init__(self, start):
        self.current = start

    def __iter__(self):
        return self  # 迭代器返回自己

    def __next__(self):
        if self.current <= 0:
            raise StopIteration  # 结束迭代
        self.current -= 1
        return self.current + 1

# 使用
