for num in cd:
    print(num, end=' ')  # 5 4 3 2 1
print()

# 自定义可迭代对象：range的简化版
class MyRange:
    def __init__(self, start, end):
        self.start = start
        self.end = end

    def __iter__(self):
        # 返回一个新的迭代器
        return MyRangeIterator(self.start, self.end)

class MyRangeIterator:
    def __init__(self, start, end):
        self.current = start
        self.end = end

    def __iter__(self):
        return self

    def __next__(self):
        if self.current >= self.end:
            raise StopIteration
        value = self.current
        self.current += 1
        return value

for i in MyRange(1, 5):
    print(i, end=' ')  # 1 2 3 4
print()

