import time

# 理解装饰器本质
def my_decorator(func):
    @functools.wraps(func)  # 保留原函数信息
    def wrapper(*args, **kwargs):
        print(f'调用前：{func.__name__}')
        result = func(*args, **kwargs)
        print(f'调用后：{func.__name__}')
        return result
    return wrapper

@my_decorator
def say_hello(name):
    '''打招呼'''
    print(f'Hello, {name}！')

say_hello('小明')
