import json
import os
from typing import List

class AccountBook:
    """账本类，管理所有记录"""
    def __init__(self, file_path='accountbook.json'):
        self.file_path = file_path
        self.records: List[Record] = []
        self._next_id = 1
        self.load()  # 启动时加载数据

    def add_record(self, type_, amount, category, note=''):
        """添加记录"""
        record = Record(
            type=type_,
            amount=amount,
            category=category,
            note=note,
            id=self._next_id,
        )
        self._next_id += 1
        self.records.append(record)
        self.save()
        return record

    def list_records(self, type_filter=None):
        """列出记录，可按类型过滤"""
        if type_filter:
            return [r for r in self.records if r.type == type_filter]
        return self.records

    def delete_record(self, record_id):
        """删除记录"""
        for i, r in enumerate(self.records):
            if r.id == record_id:
                self.records.pop(i)
                self.save()
                return True
        return False

    def get_summary(self):
        """统计汇总"""
        total_income = sum(r.amount for r in self.records if r.type == 'income')
        total_expense = sum(r.amount for r in self.records if r.type == 'expense')
        return {
            'total_income': total_income,
            'total_expense': total_expense,
            'balance': total_income - total_expense,
        }

    def get_category_summary(self):
        """按分类统计"""
        result = {}
        for r in self.records:
            key = (r.type, r.category)
            result[key] = result.get(key, 0) + r.amount
        return result

    def save(self):
        """保存到JSON文件"""
        data = {
            'next_id': self._next_id,
            'records': [r.to_dict() for r in self.records],
        }
        with open(self.file_path, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    def load(self):
        """从JSON文件加载"""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            self._next_id = data.get('next_id', 1)
            self.records = [Record.from_dict(r) for r in data.get('records', [])]
        except (FileNotFoundError, json.JSONDecodeError):
            self.records = []
            self._next_id = 1

def main():
    book = AccountBook()
    while True:
        print('\n===== 个人记账本 =====')
        print('1. 记一笔收入')
        print('2. 记一笔支出')
        print('3. 查看所有记录')
        print('4. 统计汇总')
        print('5. 分类统计')
        print('6. 删除记录')
        print('0. 退出')
        choice = input('请选择：').strip()

        if choice == '0':
            print('再见！')
            break
        elif choice in ('1', '2'):
            type_ = 'income' if choice == '1' else 'expense'
            try:
                amount = float(input('金额：'))
                if amount <= 0:
                    print('金额必须大于0')
                    continue
                category = input('分类（如餐饮/工资/交通）：').strip()
                note = input('备注（可空）：').strip()
                book.add_record(type_, amount, category, note)
                print('记录成功！')
            except ValueError:
                print('金额输入无效！')
        elif choice == '3':
            print('\n--- 所有记录 ---')
            records = book.list_records()
            if not records:
                print('暂无记录')
            for r in records:
                print(r)
        elif choice == '4':
            s = book.get_summary()
            print(f"\n总收入：{s['total_income']}元")
            print(f"总支出：{s['total_expense']}元")
            print(f"结余：{s['balance']}元")
        elif choice == '5':
            print('\n--- 分类统计 ---')
            cat = book.get_category_summary()
            for (type_, category), amount in cat.items():
                icon = '💰' if type_ == 'income' else '💸'
                print(f'{icon} {category}：{amount}元')
        elif choice == '6':
            try:
                rid = int(input('输入要删除的记录ID：'))
                if book.delete_record(rid):
                    print('删除成功！')
                else:
                    print('未找到该ID的记录')
            except ValueError:
                print('ID必须为数字')
        else:
            print('无效选择，请重试')

